mapper.select:
SELECT A.FINPROD_ID finprodId, A.FINPROD_MARKET_ID finprodMarketId, A.FINPROD_NAME finprodName, A.FINPROD_TYPE2 finprodType2, A.CCY ccy, A.VDATE vdate, A.MDATE mdate, A.PROFIT_TYPE profitType,
T2.CUSTOMER_NAME issuer,
A.CALENDAR_ID calendarId,
T1.CUSTOMER_NAME trusteeId,
T.CUSTOMER_NAME manager, A.ISSUE_AMT issueAmt, A.CAPI_INCOME_FEATURE capiIncomeFeature, B.TYPE_1 assetType, B.TYPE_6 category, B.TYPE_7 type,
B.TYPE_9 type9, B.TYPE_10 type10, B.TYPE_11 type11, B.TYPE_12 type12, C.PUR_SPEED purSpeed, C.RED_SPEED redSpeed, C.DATA_SOURCE dataSource,
FPR.RECOMMENDER recommender, A.UPDATE_USER as updateUser, MCP.COUNTER_NAME recommenderName
FROM FIN_PRODUCT A inner join FIN_PRODUCT_TYPE B on A.FINPROD_ID = B.FINPROD_ID inner join FIN_PRODUCT_ADD C on A.FINPROD_ID = C.FINPROD_ID
LEFT JOIN FIN_PRODUCT_RECOMMENT FPR ON FPR.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID
LEFT JOIN MST_CUSTOMER_INFO T ON T.CUSTOMER_ID = A.MANAGER
LEFT JOIN MST_CUSTOMER_INFO T1 ON T1.CUSTOMER_ID = A.ISSUER LEFT JOIN MST_CUSTOMER_INFO T2 ON T2.CUSTOMER_ID = A.TRUSTEE_ID
WHERE 1=1
AND A.FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
#{category,jdbcType=VARCHAR}
#{type,jdbcType=VARCHAR}
AND A.FINPROD_TYPE = #{FINPROD_TYPE_TG_F17, jdbcType = VARCHAR} AND A.PROFIT_TYPE in (#{PROFIT_TYPE_01},#{PROFIT_TYPE_02},#{PROFIT_TYPE_03})
AND A.PROFIT_TYPE = #{profitType, jdbcType = VARCHAR}
AND TO_CHAR(A.VDATE,'yyyy-MM-dd') > = #{startVDate}
AND TO_CHAR(A.VDATE,'yyyy-MM-dd') < = #{endVDate}
AND TO_CHAR(A.MDATE,'yyyy-MM-dd') > = #{startMDate}
AND TO_CHAR(A.MDATE,'yyyy-MM-dd') < = #{endMDate}
AND A.MANAGER = #{manager,jdbcType=VARCHAR}
AND A.ISSUER = #{issuer,jdbcType=VARCHAR}
AND A.TRUSTEE_ID = #{trusteeId,jdbcType=VARCHAR}
AND B.TYPE_1 = #{assetType,jdbcType=VARCHAR}
#{type9,jdbcType=VARCHAR}
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
#{type12,jdbcType=VARCHAR}

SELECT
MST_CUSTOMER_INFO.CUSTOMER_ID id,
MST_CUSTOMER_INFO.CUSTOMER_NAME text,

MST_CUSTOMER_INFO_ADD.INSITITUTE_CODE col
FROM MST_CUSTOMER_INFO
LEFT JOIN MST_CUSTOMER_INFO_ADD ON MST_CUSTOMER_INFO.CUSTOMER_ID = MST_CUSTOMER_INFO_ADD.CUSTOMER_ID




        (
        MST_CUSTOMER_INFO.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
        OR
        MST_CUSTOMER_INFO.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
        OR
        MST_CUSTOMER_INFO.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
        )



        (
        MST_CUSTOMER_INFO.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
        OR
        MST_CUSTOMER_INFO.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
        OR
        MST_CUSTOMER_INFO.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
        )


        AND MST_CUSTOMER_INFO.IS_ASSTE_MANAGER = #{IS_ASSTE_MANAGER}


        AND MST_CUSTOMER_INFO.IS_TRUSTER = #{IS_TRUSTER}


        AND MST_CUSTOMER_INFO.IS_ISSUER = #{IS_ISSUER}


        AND MST_CUSTOMER_INFO.IS_FINANCIER = #{IS_FINANCIER}



        AND MST_CUSTOMER_INFO.IS_GUARANTEE = #{IS_GUARANTEE}




        AND MST_CUSTOMER_INFO.IS_INVEST_ADVISER = #{IS_INVEST_ADVISER}
